Definition cpy_fb (b0 fb : Z) : Z := ((4 * (b0 / 4)) mod 2 ^ 64 + Z.land fb 2) mod 2 ^ 64.
Lemma cpy_fb_facts b0 fb : 0 <= b0 < 256 -> 0 <= fb < 256 -> 0 <= cpy_fb b0 fb < 256 /\ Z.testbit (cpy_fb b0 fb) 0 = false /\ Z.land (cpy_fb b0 fb) 2 = Z.land fb 2.
