Section Key.
Variables (L : asan_layout) (ar : asan_run).

Lemma free_key (M Mk : word -> option byte) (p0f s spc E r fp0 : Z) (RC : list Z) :
  HAR.rchain L ar M E fp0 RC -> fp0 <> E + 8 -> 16 <= E -> E mod 8 = 0 -> ar_stack_top ar <= 2 ^ 47 ->
  (forall x : word, E <= bv_unsigned x < ar_stack_top ar -> Mk x = M x) ->
  cell_is (hl_segs L) Mk (E - 8) 8 r -> 0 <= r < 2 ^ 64 ->
  cell_is (hl_segs L) Mk (E - 16) 8 fp0 -> 0 <= fp0 < 2 ^ 64 ->
  4096 <= s < 2 ^ 64 -> E <> spc + 8 ->
  exists Kt, In Kt (PQATSTW.fkeys3 p0f s r RC) /\ HAR.ukey L ar p0f Mk spc s E Kt.
Proof.
  intros RCH NE8 E16 E8 TOP AG C8 Hr C16 Hfp Hs NEs.
  destruct (HAR.fvalid_dec ar (ar_stack_bottom ar) spc) as [V|NV].
  2:{ exists [p0f]. split; [left; reflexivity| left; split; [exact NV| reflexivity]]. }
  destruct (HAR.fvalid_dec ar spc E) as [V2|NV2].
  2:{ exists (HAR.akey p0f [s]). split; [right; left; reflexivity|].
      apply (HAR.ukey_intro L ar); [exact V| exact Hs| exact NEs| apply HAR.rc_stop; exact NV2]. }
  destruct (Z_lt_dec r 4096) as [LO|HI].
  - exists (HAR.akey p0f [s]). split; [right; left; reflexivity|].
    apply (HAR.ukey_intro L ar); [exact V| exact Hs| exact NEs|]. apply (HAR.rc_low L ar Mk spc E r V2 C8). lia.
  - exists (HAR.akey p0f (s :: r :: RC)). split; [right; right; left; reflexivity|].
    apply (HAR.ukey_intro L ar); [exact V| exact Hs| exact NEs|].
    apply (HAR.rc_cons L ar Mk spc E r fp0 RC V2 C8 ltac:(lia) C16 Hfp).
    apply (HAR.rchain_frame_sp L ar M Mk E fp0 RC RCH E16 E8 NE8 ltac:(lia)). exact AG.
Qed.
End Key.
