(* [comment removed for export] *)
Section Stmt.
Context {SCFG_P0 : ScfgP}.
Variables (segs : list Segment) (A : pm_addrs) (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Definition cmp11d_specG (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r x y fbx fby : Z) (pn x0 x1 y0 y1 : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 x -> getr R (reg 11) = Z_to_bv 64 y ->
    PMSPA.aobjA FF x 32 -> x mod 8 = 0 -> PMSPA.accA M x 32 -> PQATSW2.bdyn_at segs M x fbx 1%nat pn x0 x1 -> Z.testbit fbx 1 = false -> In (pn, 64) LB ->
    PMSPA.aobjA FF y 32 -> y mod 8 = 0 -> PMSPA.accA M y 32 -> PQATSS.binl_at segs M y fby 1%nat y0 y1 -> Z.testbit fby 1 = false ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 (PQATSC.cmp3 x0 y0) ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr h) [] M M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.
End Stmt.
Definition cmp11d_spec {SCFG_P0 : ScfgP} (L : asan_layout) (ar : asan_run) (HI : asan_iface) : Prop :=
  cmp11d_specG RSEGS PnLayoutA.ADDR_A L ar HI PQATSC.CMP_A PQATSC.CMP_H.

